state.listenCounts=state.listenCounts||{};state.listenSeconds=state.listenSeconds||{};state.skips=state.skips||{};
state.position=Math.max(0,Number(state.position)||0);state.volume=Number.isFinite(state.volume)?state.volume:65;
let sheet=null,playlistFilter='',editingOrder=false,gesture=null,suppressClick=false,lastScroll=0;
const customCovers=new Map(Object.entries(JSON.parse(localStorage.getItem('vitra-mobile-covers')||'{}')).map(([k,v])=>[Number(k),v]));
