const time=n=>Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0');
function save(){state.catalog=songs.slice(6);state.revision=(Number(state.revision)||0)+1;const persist={...state,playing:false};window.openai?.setWidgetState?.({modelContent:{demo:'Vitra iPhone',pantalla:state.page,cancion:songs[state.song]?.t,favoritas:state.favorites.length},privateContent:persist})?.catch(()=>{});}
function notice(text){toast.textContent=text;toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.hidden=true,2200);}
function navigate(page){clearTimeout(searchTimer);searchRequest?.abort();state.page=page;expanded.hidden=true;closeSheet();main.scrollTop=0;playlistFilter='';editingOrder=false;render();save();}
function playlistArt(index,cl=''){if(customCovers.has(index))return `<div class="art ${cl}"><img class="custom-cover" src="${customCovers.get(index)}" alt="Portada personalizada"></div>`;return art({...songs[index%songs.length],t:state.playlists[index]},cl);}
function playlist(index){return state.playlistData[index]||(state.playlistData[index]={tracks:[]});}
function recordChoice(index){state.listenCounts[index]=Math.min(1000,(Number(state.listenCounts[index])||0)+1);state.recentChoices=[index,...(state.recentChoices||[]).filter(x=>x!==index)].slice(0,12);}
const musicTraits=[['urbano','enérgico'],['urbano','oscuro'],['urbano','melódico'],['urbano','melódico'],['urbano','enérgico'],['urbano','melódico']];
function score(index){const artist=songs[index].a;let affinity=0,style=0;for(let j=0;j<songs.length;j++){const shared=(musicTraits[index]||[]).filter(t=>(musicTraits[j]||[]).includes(t)).length;style+=shared*((state.listenSeconds[j]||0)/120+(state.favorites.includes(j)?1:0));}for(let j=0;j<songs.length;j++)if(songs[j].a===artist)affinity+=(state.listenCounts[j]||0)*1.5+Math.min(12,(state.listenSeconds[j]||0)/30)+(state.favorites.includes(j)?5:0)-(state.skips[j]||0)*2;return affinity+Math.min(12,style)-(state.hiddenArtists.includes(artist)?20:0)+(state.favorites.includes(index)?4:0)-(state.skips[index]||0)*3-(state.listenCounts[index]||0)*.7-((state.recentChoices||[]).slice(0,2).includes(index)?2:0);}
function recommended(){const ranked=songs.map((s,i)=>i).filter(i=>!state.hiddenSongs.includes(i)).sort((a,b)=>score(b)-score(a)||a-b);if(ranked.length<3)return ranked;const first=ranked[0],different=ranked.find(i=>songs[i].a!==songs[first].a&&!(state.recentChoices||[]).slice(0,2).includes(i));if(different!==undefined){ranked.splice(ranked.indexOf(different),1);ranked.splice(Math.min(2,ranked.length),0,different);}const limited=new Set();return ranked.filter(i=>{const artist=songs[i].a;if(!state.hiddenArtists.includes(artist))return true;if(limited.has(artist))return false;limited.add(artist);return true;});}
function history(){return Array.isArray(state.searchHistory)?state.searchHistory:[{kind:'song',index:0},{kind:'artist',name:'Clarent'},{kind:'song',index:3}];}
