function row(index,order=false){const s=songs[index];return `<div class="feature-row"><button class="track-main" data-song="${index}">${art(s)}${meta(s)}</button>${order?`<button data-move="${index}" data-dir="-1" aria-label="Subir ${s.t}">${icon('chevron-up')}</button><button data-move="${index}" data-dir="1" aria-label="Bajar ${s.t}">${icon('chevron-down')}</button>`:`<span class="track-duration">${s.d}</span><button class="track-more" data-menu="${index}" aria-label="Opciones de ${s.t}">${icon('ellipsis')}</button>`}</div>`;}
function rows(indices=songs.map((s,i)=>i),order=false){return indices.map(i=>row(i,order)).join('');}

const artistKey=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
state.artistProfiles=state.artistProfiles&&typeof state.artistProfiles==='object'?state.artistProfiles:{};
let artistResults=[],artistResultQuery='',artistRequest=null;
const artistPending=new Set();
function profileFor(name){return state.artistProfiles[artistKey(name)];}
function artistAvatar(name){const p=profileFor(name);return p&&/^\/api\/artist-art\/UC[A-Za-z0-9_-]{22}$/.test(p.photo||'')?'<img class="artist-photo" src="'+esc(p.photo)+'" alt="'+esc(p.name)+'">':icon('mic-2');}
function artistRow(name){return '<button class="row" data-artist="'+esc(name)+'"><span class="artist-avatar">'+artistAvatar(name)+'</span><div class="meta"><strong>'+esc(name)+'</strong><small>Artista</small></div>'+icon('chevron-right')+'</button>';}
function artistMatches(track,name){const p=profileFor(name);if(Array.isArray(track.artists)&&track.artists.length)return track.artists.some(a=>p&&a.id===p.id||artistKey(a.name)===artistKey(name));return artistKey(track.a).includes(artistKey(name));}
async function loadArtistProfile(name){const key=artistKey(name);if(profileFor(name)||artistPending.has(key))return;artistPending.add(key);try{const response=await fetch('/api/artists?q='+encodeURIComponent(name));if(!response.ok)throw Error('Artista no disponible');const body=await response.json(),p=body.artists.find(a=>artistKey(a.name)===key)||body.artists[0];if(p){state.artistProfiles[key]=p;state.artistProfiles[artistKey(p.name)]=p;save();if(state.page==='artist'&&artistKey(state.artist)===key)render();}}catch{}finally{artistPending.delete(key);}}
async function queueArtistSearch(query){artistRequest?.abort();artistResults=[];artistResultQuery=query;const request=artistRequest=new AbortController();if(!query.trim())return;try{const response=await fetch('/api/artists?q='+encodeURIComponent(query),{signal:request.signal});if(!response.ok)throw Error('Artistas no disponibles');const body=await response.json();if(state.query!==query||state.page!=='search')return;artistResults=body.artists.filter(p=>artistKey(p.name).includes(artistKey(query)));for(const p of artistResults)state.artistProfiles[artistKey(p.name)]=p;main.querySelector('.results').innerHTML=searchResults();icons();save();}catch(error){if(error.name!=='AbortError'&&state.page==='search'&&state.query===query)notice('No se pudo cargar el perfil del artista.');}}
function searchResults(){const q=artistKey(state.query);if(!q)return history().map(x=>x.kind==='song'&&songs[x.index]?row(x.index):x.kind==='artist'?artistRow(x.name):'').join('')||'<p class="empty">Tus búsquedas aparecerán aquí.</p>';const artists=artistResultQuery===state.query?artistResults:Object.values(state.artistProfiles).filter(p=>artistKey(p.name).includes(q));const unique=[...new Map(artists.map(p=>[p.id,p])).values()];const tracks=songs.map((s,i)=>i).filter(i=>artistKey(songs[i].t+' '+songs[i].a).includes(q));return unique.map(p=>artistRow(p.name)).join('')+rows(tracks)||'<p class="empty">No hay resultados.</p>';}

function header(title,action='settings'){return `<header class="mobile-header"><h1>${title}</h1><button class="round" data-page="${action}" aria-label="Configuración">${icon('user-round')}</button></header>`;}
function back(page,label){return `<button class="back" data-page="${page}">${icon('chevron-left')} ${label}</button>`;}
const artistCollections=new Map(),albumCollections=new Map(),collectionPending=new Set(),collectionErrors=new Map();
function mergeCatalogueTrack(t){let index=songs.findIndex(s=>t.appleId?s.appleId===t.appleId:!!t.vid&&s.vid===t.vid);if(index<0){index=songs.length;songs.push(t);}else Object.assign(songs[index],t);return index;}
async function loadArtistCollection(name){const p=profileFor(name);if(!p||artistCollections.has(p.id)||collectionPending.has(p.id))return;collectionPending.add(p.id);collectionErrors.delete(p.id);try{const response=await fetch('/api/artist-profile/'+encodeURIComponent(p.id));const body=await response.json();if(!response.ok)throw Error(body.error||'No se pudo cargar el artista');body.topSongs.forEach(mergeCatalogueTrack);for(const a of [...body.albums,...body.singles])albumCollections.set(a.id,a);if(body.latest){albumCollections.set(body.latest.id,body.latest);body.latest.tracks?.forEach(mergeCatalogueTrack);}artistCollections.set(p.id,body);save();}catch(error){collectionErrors.set(p.id,'No se pudo cargar el catálogo.');}finally{collectionPending.delete(p.id);if(state.page==='artist'&&profileFor(state.artist)?.id===p.id)render();}}
async function loadFullAlbum(id){if(albumCollections.get(id)?.tracks||collectionPending.has(id))return;collectionPending.add(id);collectionErrors.delete(id);try{const response=await fetch('/api/album/'+encodeURIComponent(id));const body=await response.json();if(!response.ok)throw Error(body.error||'No se pudo cargar el álbum');body.tracks.forEach(mergeCatalogueTrack);albumCollections.set(id,body);save();}catch{collectionErrors.set(id,'No se pudo cargar el álbum.');}finally{collectionPending.delete(id);if(state.page==='artist-album'&&state.albumId===id)render();}}
function releaseTile(a){return `<button class="release-tile" data-catalog-album="${esc(a.id)}" aria-label="Abrir ${esc(a.title)}"><img src="${esc(a.art)}" alt="Portada de ${esc(a.title)}" loading="lazy"><strong>${esc(a.title)}</strong><small>${esc(a.year)}</small></button>`;}
function topSongRow(t,rank){const i=mergeCatalogueTrack(t);return `<div class="artist-top-row"><button data-song="${i}" class="top-track"><img src="${esc(t.art)}" alt="Portada de ${esc(t.t)}" loading="lazy"><span><strong>${esc(t.t)}</strong><small>${esc(t.album||t.a)}</small></span></button><button data-menu="${i}" aria-label="Opciones de ${esc(t.t)}">${icon('ellipsis')}</button></div>`;}
function renderArtistPage(){const name=state.artist||'Clarent',p=profileFor(name);loadArtistProfile(name);const data=p&&artistCollections.get(p.id);if(p&&!data&&!collectionErrors.has(p.id))loadArtistCollection(name);const top=data?.topSongs||[],first=top[0]?songs.findIndex(s=>top[0].appleId?s.appleId===top[0].appleId:s.vid===top[0].vid):-1;const latest=data?.latest;return `<div class="artist-hero"><img src="${esc(data?.hero||p?.photo||'/icon.png')}" alt="${esc(p?.name||name)}"><div class="artist-hero-shade"></div><button class="artist-back" data-page="search" aria-label="Volver a Search">${icon('chevron-left')}</button><div class="artist-title"><h1>${esc(data?.name||p?.name||name)}</h1>${first>=0?`<button data-song="${first}" aria-label="Reproducir ${esc(name)}">${icon('play')}</button>`:''}</div></div>${!data?`<div class="catalog-loading" role="status">${collectionErrors.get(p?.id)||'Cargando lanzamientos y canciones…'}${collectionErrors.has(p?.id)?'<button data-action="retry-artist">Reintentar</button>':''}</div>`:''}${latest?`<button class="latest-release" data-catalog-album="${esc(latest.id)}"><img src="${esc(latest.art)}" alt="Portada de ${esc(latest.title)}"><span><small>${esc(latest.dateLabel||'ÚLTIMO LANZAMIENTO')}</small><strong>${esc(latest.title)}</strong><span>${esc(latest.kind)} · ${esc(latest.trackCountLabel||'')}</span></span>${icon('chevron-right')}</button>`:''}${data?`<h2>Top Songs</h2>${top.length?`<div class="top-songs-carousel" role="region" aria-label="Top Songs, desliza para ver más" tabindex="0">${Array.from({length:Math.ceil(top.length/4)},(_,column)=>`<div class="top-songs-column">${top.slice(column*4,column*4+4).map((t,n)=>topSongRow(t,column*4+n+1)).join('')}</div>`).join('')}</div>`:'<p>No hay canciones destacadas disponibles.</p>'}<h2>Álbumes</h2><div class="release-carousel" role="region" aria-label="Álbumes, desliza para ver más" tabindex="0">${data.albums.map(releaseTile).join('')||'<p>No hay álbumes disponibles.</p>'}</div>${data.singles.length?`<h2>Sencillos y EP</h2><div class="release-carousel" role="region" aria-label="Sencillos y EP, desliza para ver más" tabindex="0">${data.singles.map(releaseTile).join('')}</div>`:''}`:''}`;}
function renderCatalogueAlbum(){const id=state.albumId,a=albumCollections.get(id);if(!a?.tracks&&!collectionErrors.has(id))loadFullAlbum(id);return `<button class="back" data-page="artist">${icon('chevron-left')} ${esc(state.artist)}</button>${a?`<div class="catalog-album-header"><img src="${esc(a.art)}" alt="Portada de ${esc(a.title)}"><h1>${esc(a.title)}</h1><p>${esc(a.artist||state.artist)}</p><p>${esc(a.kind)} · ${esc(a.year)}</p></div>`:''}${a?.tracks?.length?`<div class="actions"><button data-song="${mergeCatalogueTrack(a.tracks[0])}" ${a.tracks.length?'':'disabled'}>${icon('play')} Reproducir</button></div>${a.tracks.map(t=>row(mergeCatalogueTrack(t))).join('')}`:`<p role="status">${collectionErrors.get(id)||'Cargando canciones…'}</p>${collectionErrors.has(id)?'<button data-action="retry-album">Reintentar</button>':''}`}`;}

state.discoveryQueue=Array.isArray(state.discoveryQueue)?state.discoveryQueue.filter(i=>songs[i]):[];
state.discoveryHistory=Array.isArray(state.discoveryHistory)?state.discoveryHistory.filter(i=>songs[i]):[];let discoveryGoingBack=false;
let discoveryRequest=null,discoveryPendingKey='',discoveryError='';
const songIdentity=t=>String(t.appleId||t.vid||'');
const discoveryKey=t=>songIdentity(t)||artistKey(t.a)+'|'+artistKey(t.t);
function listeningTaste(){const values=new Map();for(let i=0;i<songs.length;i++){const t=songs[i],artist=t.a.split(/,| & /)[0].trim(),key=artistKey(artist);const weight=Math.min(20,(Number(state.listenSeconds[i])||0)/90)+(state.favorites.includes(i)?5:0)+(Number(state.listenCounts[i])||0)*.25-(Number(state.skips[i])||0)*2;if(weight<=0)continue;const current=values.get(key)||{artist,weight:0};current.weight+=weight;values.set(key,current);}return [...values.values()].sort((a,b)=>b.weight-a.weight).slice(0,10).map(t=>({...t,weight:Math.min(50,t.weight)}));}
function automaticQueue(){const excluded=new Set([...state.hiddenSongs,state.song]);const manual=new Set(state.playNext.map(discoveryKey));return state.discoveryQueue.filter(i=>songs[i]&&!excluded.has(i)&&!manual.has(discoveryKey(songs[i]))&&!state.hiddenArtists.some(a=>artistKey(songs[i].a).includes(artistKey(a))));}
async function ensureDiscovery(index=state.song,force=false){const track=songs[index];if(!track)return;const key=discoveryKey(track);if(!force&&state.discoverySeedKey===key&&automaticQueue().length>4)return;if(discoveryPendingKey===key)return discoveryRequest?.promise;discoveryRequest?.controller.abort();const controller=new AbortController();discoveryPendingKey=key;discoveryError='';if(state.discoverySeedKey!==key){state.discoveryQueue=[];state.discoverySeedKey=key;}const work=(async()=>{try{const excluded=[track,...state.playNext,...state.hiddenSongs.map(i=>songs[i]).filter(Boolean)];const payload={seed:{t:track.t,a:track.a,appleId:track.appleId,vid:track.vid},taste:listeningTaste(),hiddenArtists:state.hiddenArtists,exclude:excluded.flatMap(t=>[songIdentity(t),artistKey(t.t).replace(/[^a-z0-9]/g,'')+'|'+artistKey(t.a).replace(/[^a-z0-9]/g,'')]),recent:(state.recentChoices||[]).map(i=>songs[i]&&songIdentity(songs[i])).filter(Boolean),favorites:state.favorites.map(i=>songs[i]&&songIdentity(songs[i])).filter(Boolean),skips:Object.fromEntries(Object.entries(state.skips).filter(([i])=>songs[i]).map(([i,n])=>[songIdentity(songs[i]),n]))};const response=await fetch('/api/recommendations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:controller.signal});const body=await response.json();if(!response.ok)throw Error(body.error||'No se pudieron cargar las recomendaciones');if(discoveryKey(songs[state.song])!==key)return;state.discoveryQueue=body.tracks.map(mergeCatalogueTrack);state.discoveryGenre=body.genre;save();}catch(error){if(error.name!=='AbortError')discoveryError='No se pudieron cargar las recomendaciones. Inténtalo de nuevo.';}finally{if(discoveryPendingKey===key){discoveryPendingKey='';discoveryRequest=null;if(sheet?.kind==='upcoming')drawContinuation();}}})();discoveryRequest={controller,promise:work};return work;}
function drawContinuation(){sheet={kind:'upcoming',index:state.song};sheetHost.hidden=false;const pending=state.playNext.map((track,q)=>{const i=mergeCatalogueTrack(track);return '<div class="queued-track">'+row(i)+'<button data-removequeued="'+q+'" aria-label="Quitar '+esc(track.t)+' de Reproducir después">'+icon('x')+'</button></div>';}).join('');const queue=automaticQueue();let manual='';if(['playlist','album'].includes(state.continuationMode)){const list=state.playContext||[],at=list.indexOf(state.song);const remaining=list.slice(at+1).filter(i=>songs[i]);if(remaining.length)manual='<h3>'+ (state.continuationMode==='album'?'En este álbum':'En tu playlist')+'</h3>'+remaining.map(i=>row(i)).join('');}sheetHost.innerHTML=`<div class="sheet-scrim" data-action="close-sheet"></div><div class="sheet-panel continuation-panel" role="dialog" aria-label="Continue Playing"><div class="top"><h3>Continue Playing</h3><button data-action="close-sheet" aria-label="Cerrar opciones">${icon('x')}</button></div>${pending?'<h3>Reproducir después</h3>'+pending:''}${manual}<h3>Para ti</h3>${queue.map(i=>row(i)).join('')||'<p role="status">'+(discoveryError||(discoveryPendingKey?'Buscando música similar…':'No hay recomendaciones disponibles para esta canción.'))+'</p>'}${discoveryError?'<button data-action="retry-discovery">Reintentar</button>':''}</div>`;icons();}
async function playDiscoveryNext(){const from=state.song;await ensureDiscovery();if(state.song!==from)return;const queue=automaticQueue();if(!queue.length){notice(discoveryError||'No hay recomendaciones disponibles para esta canción.');return;}const next=state.shuffle?queue[Math.floor(Math.random()*Math.min(6,queue.length))]:queue[0];state.discoveryQueue=state.discoveryQueue.filter(i=>i!==next);state.discoverySeedKey=discoveryKey(songs[next]);state.continuationMode='discovery';startTrack(next,{keepContext:true});}


function downloadedPage(){const downloaded=[...window.VitraOffline.items.values()];return back('library','Biblioteca')+'<h1>Descargadas</h1><p>'+downloaded.length+(downloaded.length===1?' canción · ':' canciones · ')+(downloaded.reduce((n,r)=>n+r.size,0)/1048576).toFixed(1)+' MB</p>'+(downloaded.length?downloaded.sort((a,b)=>b.date-a.date).map(r=>row(mergeCatalogueTrack({...r.track,art:r.track.offlineArt||r.track.art}))).join(''):'<p class="empty">Descarga canciones desde su menú para escucharlas sin conexión.</p>');}
async function handleDownload(index){const song=songs[index];if(window.VitraOffline.pending.has(window.VitraOffline.key(song)))return;closeSheet();try{if(window.VitraOffline.has(song)){await window.VitraOffline.remove(song);notice('Descarga eliminada del dispositivo.');}else{notice('Descargando '+song.t+'…');await window.VitraOffline.download(song);notice('Disponible sin conexión: '+song.t);}}catch(e){notice(e.name==='QuotaExceededError'?'No queda espacio para esta descarga.':e.message||'No se pudo guardar la descarga.');}}
window.addEventListener('vitra-downloads-changed',()=>{if(state.page==='downloads')render();if(sheet?.kind==='menu')drawSheet();});
window.VitraOffline.ready.then(()=>{for(const r of window.VitraOffline.items.values())mergeCatalogueTrack({...r.track,art:r.track.offlineArt||r.track.art});});

