if(state.page==='library')main.innerHTML=header('Biblioteca')+`<div class="librarylinks">${[['playlists','list-music','Playlists'],['artists','mic-2','Artistas'],['albums','disc-3','Álbumes'],['songs','music-2','Canciones'],['favorites','star','Favoritas'],['history','history','Historial'],['downloads','download','Descargadas']].map(([p,i,t])=>`<button class="row" data-page="${p}">${icon(i)}<span>${t}</span>${icon('chevron-right')}</button>`).join('')}</div><h2>Añadido recientemente</h2><div class="grid">${songs.slice(0,4).map((s,i)=>`<button class="tile" data-release="${i}">${art(s)}<strong>${s.t}</strong><p>${s.a}</p></button>`).join('')}</div>`;
if(state.page==='playlists')main.innerHTML=back('library','Biblioteca')+`<div class="top"><h1>Playlists</h1><button class="round" data-page="create" aria-label="Crear playlist">${icon('plus')}</button></div>`+state.playlists.map((p,i)=>`<button class="row" data-playlist="${i}">${playlistArt(i)}<div class="meta"><strong>${esc(p)}</strong><small>${playlist(i).tracks.length} canciones</small></div>${icon('chevron-right')}</button>`).join('');
if(state.page==='playlist'){const i=state.playlist||0;main.innerHTML=back('playlists','Playlists')+`<button class="playlist-cover-edit" data-action="cover" aria-label="Cambiar portada">${playlistArt(i,'bigcover')}<span>${icon('camera')} Cambiar portada</span></button><div class="center"><h2>${esc(state.playlists[i])}</h2><p>${playlist(i).tracks.length} canciones</p></div><div class="actions"><button data-action="play-list">${icon('play')} Reproducir</button><button data-action="mix-list">${icon('shuffle')} Aleatorio</button></div><div class="playlist-tools"><input type="search" placeholder="Buscar en esta playlist" aria-label="Buscar en esta playlist"><button class="pill" data-action="reorder">${editingOrder?'Listo':'Ordenar'}</button></div><div class="playlist-results">${playlistRows()}</div><button class="pill" data-action="addtracks">${icon('plus')} Añadir canciones</button><input type="file" class="cover-file" accept="image/*" aria-label="Elegir foto de portada" hidden>`;}
if(state.page==='songs'||state.page==='favorites'||state.page==='history'){const title={songs:'Canciones',favorites:'Favoritas',history:'Historial'}[state.page];const indices=state.page==='songs'?songs.map((s,i)=>i):state.page==='favorites'?state.favorites:(state.recentChoices||[]);main.innerHTML=back('library','Biblioteca')+`<h1>${title}</h1>`+(indices.length?rows(indices):'<p class="empty">Todavía no hay canciones aquí.</p>');}
