(()=>{
 const root=document.getElementById('vitra-iphone');let drag=null,blockClickUntil=0;
 root.addEventListener('dragstart',event=>{if(event.target.closest('.release-carousel,.top-songs-carousel'))event.preventDefault();});
 root.addEventListener('pointerdown',event=>{const rail=event.target.closest('.release-carousel,.top-songs-carousel');if(!rail||event.pointerType!=='mouse'||event.button!==0)return;drag={rail,id:event.pointerId,x:event.clientX,y:event.clientY,left:rail.scrollLeft,moved:false};});
 root.addEventListener('pointermove',event=>{if(!drag||event.pointerId!==drag.id)return;const dx=event.clientX-drag.x,dy=event.clientY-drag.y;if(!drag.moved){if(Math.abs(dy)>Math.abs(dx)&&Math.abs(dy)>8){drag=null;return;}if(Math.abs(dx)<8)return;drag.moved=true;drag.rail.classList.add('is-dragging');drag.rail.setPointerCapture(event.pointerId);}event.preventDefault();drag.rail.scrollLeft=drag.left-dx;},{passive:false});
 const finish=event=>{if(!drag||event.pointerId!==drag.id)return;const current=drag;drag=null;if(current.moved){blockClickUntil=Date.now()+400;current.rail.classList.remove('is-dragging');if(current.rail.hasPointerCapture(event.pointerId))current.rail.releasePointerCapture(event.pointerId);}};
 root.addEventListener('pointerup',finish);root.addEventListener('pointercancel',finish);
 root.addEventListener('click',event=>{if(Date.now()<blockClickUntil&&event.target.closest('.release-carousel,.top-songs-carousel')){event.preventDefault();event.stopImmediatePropagation();}},true);
})();

/* Animate only overflowing titles, with a readable pause at each end. */
(()=>{const selector='.mini .now .meta strong';let scheduled=false;
function measure(){scheduled=false;document.querySelectorAll(selector).forEach(el=>{let span=el.firstElementChild;if(!span||!span.classList.contains('marquee-title')){span=document.createElement('span');span.className='marquee-title';span.textContent=el.textContent;el.replaceChildren(span);}const distance=Math.max(0,span.scrollWidth-el.clientWidth);if(distance<3){span.style.animation='none';delete span.dataset.distance;el.classList.remove('scrolling-title');return;}el.classList.add('scrolling-title');if(span.dataset.distance===String(distance))return;span.dataset.distance=distance;span.style.setProperty('--marquee-distance',(-distance)+'px');span.style.setProperty('--marquee-duration',(distance/26*2+5)+'s');span.style.animation='';});}
function schedule(){if(!scheduled){scheduled=true;requestAnimationFrame(measure);}}
new MutationObserver(schedule).observe(document.querySelector('.mini'),{childList:true,subtree:true,characterData:true});new ResizeObserver(schedule).observe(document.querySelector('.mini'));schedule();
})();

